#include <string>
#include <cassert>

std::string get_welcome_message(const std::string &username) {
    return "Welcome, " + username + "!";
}

int main() {
    // Test case 1: Normal username
    assert(get_welcome_message("user123") == "Welcome, user123!");

    // Test case 2: Empty username
    assert(get_welcome_message("") == "Welcome, !");

    // Test case 3: Special characters in username
    assert(get_welcome_message("user@123") == "Welcome, user@123!");

    return 0;
}
